WITH remaining_keys AS (SELECT country, id FROM sessions INTERSECT SELECT country, id FROM sessions WHERE customer_id IN (4, 23, 36)), reconciled AS (SELECT s.* FROM sessions s JOIN remaining_keys k ON s.country = k.country AND s.id = k.id) SELECT browser, COUNT(DISTINCT id) AS distinct_ids, MAX(started_at) AS ended_at, MAX(started_at) AS last_seen FROM reconciled GROUP BY browser ORDER BY browser NULLS FIRST;
